const store = new Map();
let providerCalls = 0;
function fingerprint(body){ return JSON.stringify(body); }
function chargeProvider(body){ providerCalls++; return { id: 'ch_' + providerCalls, amount: body.amount }; }

function handleCharge(key, body){
  const fp = fingerprint(body);
  const existing = store.get(key);
  if (existing){
    if (existing.fp !== fp) throw new Error('mismatch');
    return { replayed: true, resp: existing.resp };
  }
  const resp = chargeProvider(body);
  store.set(key, { fp, resp });
  return { replayed: false, resp };
}

const a1 = handleCharge('K1', { amount: 500 });
console.log('first', a1.replayed, a1.resp.id);
const a2 = handleCharge('K1', { amount: 500 });
console.log('retry', a2.replayed, a2.resp.id);
const b1 = handleCharge('K2', { amount: 700 });
console.log('other', b1.replayed, b1.resp.id);
console.log('providerCalls', providerCalls);
